import re, os, subprocess

hits = []
for root, dirs, files in os.walk('.'):
    if '/.git' in root: continue
    for f in files:
        if not f.endswith(('.c','.h')): continue
        p = os.path.join(root, f)
        try:
            src = open(p, errors='ignore').read()
        except Exception:
            continue
        lines = src.split('\n')
        # find timer callback registrations
        for i, ln in enumerate(lines):
            if re.search(r'timer_setup\s*\(|setup_timer\s*\(|\.function\s*=\s*|hrtimer_init\s*\(|INIT_DELAYED_WORK\s*\(', ln):
                hits.append((p, i+1, ln.strip()[:120]))
print("TIMER_REGISTRATIONS:", len(hits))
for h in hits[:400]:
    print(h[0], h[1], h[2])
EOF

